package com.fitagent.domain

import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.time.LocalDate
import java.time.ZoneOffset

/**
 * Readiness v2 must match the Python implementation exactly. fixtures/readiness_v2.json is generated by
 * fixtures/generate_readiness_fixtures.py (Python) and replayed here.
 */
class ReadinessV2Test {
    private val zone = ZoneOffset.UTC

    @Test fun matchesPythonOnSharedFixtures() {
        val file = File("../fixtures/readiness_v2.json")
        val cases = JsonParser.parseString(file.readText()).asJsonArray
        assertTrue("expected at least 40 shared cases", cases.size() >= 40)
        for (c in cases) {
            val case = c.asJsonObject
            val name = case["name"].asString
            val today = LocalDate.parse(case["today"].asString)
            val days = case["days"].asJsonArray.map { dayFrom(it.asJsonObject) }
            val workouts = case["workouts"].asJsonArray.mapIndexed { i, w ->
                val o = w.asJsonObject
                val start = LocalDate.parse(o["date"].asString).atTime(7, 0).toInstant(zone).toEpochMilli()
                val minutes = o["minutes"].asLong
                Workout(i.toLong(), "w$i", WorkoutType.fromName(o["type"].asString), null, start, start + minutes * 60_000,
                    minutes * 60, 0.0, WorkoutSource.APP)
            }
            val r = computeReadiness(days, workouts, today, zone)
            val expected = case["expected"].asJsonObject
            val comps = expected["components"].asJsonObject.entrySet().associate { it.key to it.value.asInt }
            assertEquals("$name: components", comps, r.components.toMap())
            assertEquals("$name: score", expected["score"].asInt, r.score)
            assertEquals("$name: band", expected["band"].asString, r.band.name)
        }
    }

    @Test fun normalLoadDoesNotPropUpPoorRecovery() {
        val today = LocalDate.of(2026, 10, 30)
        val days = (14 downTo 1).map { DayActivity(today.minusDays(it.toLong()), steps = 8000, sleepMinutes = 450, restingHr = 58) } +
            DayActivity(today, sleepMinutes = 270, restingHr = 66)
        val workouts = (1..27 step 2).map { ago ->
            val start = today.minusDays(ago.toLong()).atTime(7, 0).toInstant(zone).toEpochMilli()
            Workout(ago.toLong(), "w$ago", WorkoutType.RUN, null, start, start + 1_800_000, 1800, 0.0, WorkoutSource.APP)
        }
        val r = computeReadiness(days, workouts, today, zone)
        assertTrue("load ≤ 1.3 is not scored when body data exists", "load" !in r.components)
        assertEquals(Band.RECOVER, r.band)
    }

    private fun dayFrom(o: JsonObject): DayActivity {
        fun int(k: String) = o[k]?.takeUnless { it.isJsonNull }?.asInt
        fun dbl(k: String) = o[k]?.takeUnless { it.isJsonNull }?.asDouble
        val deep = int("sleep_deep_min"); val rem = int("sleep_rem_min"); val light = int("sleep_light_min"); val awake = int("sleep_awake_min")
        val hasStages = listOf(deep, rem, light).any { it != null && it > 0 }
        return DayActivity(
            date = LocalDate.parse(o["day"].asString),
            steps = int("steps")?.toLong() ?: 0,
            sleepMinutes = int("sleep_minutes"),
            restingHr = int("resting_hr"),
            sleepStages = if (hasStages) SleepStages(deep ?: 0, rem ?: 0, light ?: 0, awake ?: 0) else null,
            night = NightSignals(hrvMs = dbl("hrv_ms"), spo2Avg = dbl("spo2_avg"), respiratoryRate = dbl("resp_rate"),
                skinTempDelta = dbl("skin_temp_delta")),
        )
    }
}
